const receivedMs = Date.now();
// Gate for every observed record.
// Output 1 = good, goes to machine_events.
// Output 2 = bad, goes to rejected_records and NOTHING else.
// A bad record must never reach the metrics.

const m = msg.payload;
let reason = null;

const timestampOK = value =>
    typeof value === 'string' &&
    /(?:Z|[+-][0-9]{2}:[0-9]{2})$/i.test(value) &&
    Number.isFinite(Date.parse(value));

if (m === null || typeof m !== 'object' || Array.isArray(m)) {
    reason = 'payload is not an object';
} else if (!Number.isInteger(m.asset)) {
    reason = 'asset must be an integer';
} else if (!timestampOK(m.ts_dataset) || !timestampOK(m.ts_replay)) {
    reason = 'dataset and replay timestamps need a timezone';
} else if (typeof m.items !== 'number' || !Number.isFinite(m.items) || m.items < 0) {
    reason = 'items missing, negative or non-finite';
} else if (![1, 2, 3].includes(m.status)) {
    // The audit found only status 1, 2 and 3 in this file.
    reason = 'status not in (1,2,3)';
}

if (reason) {
    node.status({fill: 'red', shape: 'ring', text: reason});
    return [null, {
        topic: 'INSERT INTO rejected_records (ts_replay, topic, reason, raw_payload) VALUES ($ts, $topic, $reason, $raw)',
        params: {
            $ts: new Date().toISOString(),
            $topic: msg.topic,
            $reason: reason,
            $raw: JSON.stringify(m)
        }
    }];
}

m.received_ms = receivedMs;
node.status({fill: 'green', shape: 'dot', text: 'machine ' + m.asset});
return [{
    topic: 'INSERT OR IGNORE INTO machine_events (source, run_id, seq, asset, ts_dataset, ts_replay, items, status, status_time, power_avg, cycle_time, power_ok, cycle_ok) VALUES ($source,$run,$seq,$asset,$tsd,$tsr,$items,$status,$stime,$power,$cycle,$pok,$cok)',
    validated_payload: m,
    params: {
        $source: m.source || 'observed',
        $run: m.run_id || null,
        $seq: m.seq === undefined ? null : m.seq,
        $asset: m.asset,
        $tsd: m.ts_dataset,
        $tsr: m.ts_replay,
        $items: m.items,
        $status: m.status,
        $stime: m.status_time,
        $power: m.power_avg,
        $cycle: m.cycle_time,
        $pok: m.power_ok ? 1 : 0,
        $cok: m.cycle_ok ? 1 : 0
    }
}, null];

let n = (flow.get('accepted') || 0) + 1;
flow.set('accepted', n);
msg.payload = n;
return msg;

let n = (flow.get('rejected') || 0) + 1;
flow.set('rejected', n);
msg.payload = n;
return msg;

const m = msg.payload;

// 1. store
const store = {
    topic: 'INSERT INTO machine_metrics (asset, ts_dataset, ts_replay, window_slots, rolling_items, items_per_slot, items_per_productive_slot, productive_share, alarm_share, cycle_time_indicator, coverage, baseline_items_per_slot, baseline_ratio, baseline_hour) VALUES ($a,$tsd,$tsr,$w,$ri,$ips,$ipps,$ps,$as,$ct,$cov,$base,$ratio,$hour)',
    params: {
        $a: m.asset, $tsd: m.ts_dataset, $tsr: m.ts_replay,
