    topic: 'machine ' + m.asset,
    payload: Math.round(m.coverage * 100)
};

return [store, chart, coverage];

const a = msg.payload;

const store = {
    topic: 'INSERT INTO machine_alerts (ts_replay, ts_dataset, asset, level, kind, recommendation, message) VALUES ($tsr,$tsd,$a,$lvl,$kind,$rec,$msg)',
