const f = msg.payload;

const store = {
    topic: 'INSERT INTO forecasts (ts_replay, asset, horizon_minutes, predicted_items, model, prediction_guarded, guard_limit) VALUES ($tsr,$a,$h,$p,$model,$guarded,$limit)',
    params: { $tsr: f.ts_replay, $a: f.asset, $h: f.horizon_minutes, $p: f.predicted_items, $model: f.model, $guarded: f.prediction_guarded ? 1 : 0, $limit: f.guard_limit }
