// EVERYTHING here is SIMULATED. It is stored in sim_* tables, which are
// kept separate from the observed tables on purpose.
const s = msg.payload;
const inserts = [];
const queues = [];
const busy = [];

for (const st of s.stages) {
    inserts.push({
        topic: 'INSERT INTO sim_state (source, run_label, ts_replay, sim_second, stage_index, stage_name, rate_per_min, configured_rate, queue_length, busy_share, starved_share, completed, avg_wait_seconds, is_bottleneck) VALUES ($src,$run,$tsr,$sec,$i,$name,$rate,$crate,$q,$busy,$starv,$done,$wait,$bn)',
        params: {
            $src: 'simulated', $run: 'live', $tsr: s.ts_replay,
            $sec: s.sim_second, $i: st.stage_index, $name: st.stage_name,
            $rate: st.rate_per_min, $crate: st.configured_rate,
            $q: st.queue_length, $busy: st.busy_share,
            $starv: st.starved_share, $done: st.completed,
            $wait: st.avg_wait_seconds, $bn: 0
        }
    });
    queues.push({ topic: st.stage_name, payload: st.queue_length });
    busy.push({ topic: st.stage_name, payload: Math.round(st.busy_share * 100) });
}

const summary = {
    payload: 'SIMULATED  completed: ' + s.line_completed +
             '   throughput: ' + s.line_throughput_per_hour + '/h' +
             '   avg wait: ' + s.avg_wait_seconds + 's' +
             '   (t=' + s.sim_second + 's)'
};

return [inserts, queues, busy, summary];

const c = msg.payload;
const store = {
    topic: 'INSERT INTO sim_commands (command_id, direction, ts_replay, sim_second, action, stage_index, detail, reason, old_rate, new_rate) VALUES ($id,$dir,$tsr,$sec,$act,$i,$detail,$reason,$old,$new)',
    params: {
        $id: c.command_id, $dir: 'command', $tsr: c.ts_replay,
