    }
};
const show = { payload: 'COMMAND -> ' + c.stage_name + ': ' + c.old_rate + ' -> ' + c.new_rate + ' tokens/min. ' + c.reason };
return [store, show];

const a = msg.payload;
const store = {
    topic: 'INSERT INTO sim_commands (command_id, direction, ts_replay, sim_second, action, stage_index, accepted, old_rate, new_rate, reason) VALUES ($id,$dir,$tsr,$sec,$act,$i,$ok,$old,$new,$reason)',
    params: {
        $id: a.command_id, $dir: 'ack', $tsr: a.ts_replay,
        $sec: a.sim_second, $act: a.action, $i: a.stage_index,
        $ok: a.accepted ? 1 : 0,
        $old: a.old_rate === undefined ? null : a.old_rate,
        $new: a.new_rate === undefined ? null : a.new_rate,
        $reason: a.reason
    }
};
const show = { payload: 'ACK ' + (a.accepted ? 'ACCEPTED' : 'REFUSED') + ' for ' + a.command_id + ': ' + a.reason };
