// node-red-node-sqlite's msg.topic mode binds msg.payload as an array.
 // Our upstream nodes use named parameters, so preserve their SQL order here.
if (typeof msg.topic !== 'string' || !msg.params) {
    node.error('SQL statement or parameters missing', msg);
    return null;
}
const names = [...msg.topic.matchAll(/\$[A-Za-z_][A-Za-z0-9_]*/g)].map(m => m[0]);
msg.payload = names.map(name =>
    Object.prototype.hasOwnProperty.call(msg.params, name) && msg.params[name] !== undefined
        ? msg.params[name] : null);
delete msg.params;
if(msg.topic.includes('company_b_events')) return [null,msg]; return [msg,null];

// SQLite emits this message only after a successful insert.
// Non-machine messages have no validated_payload and stop here.
const m = msg.validated_payload;
if (!m) return null;
return {topic: 'team12/observed/validated/' + m.asset, payload: JSON.stringify(m), qos: '0', retain: 'false'};

const p=msg.payload||{};
let s=context.get('overview')||{machineMap:{},outputHistory:{},forecastHistory:{},queueHistory:{},busyHistory:{},stages:[],completed:0,forecastText:'Waiting for forecast',advice:'Waiting for decision',action:'No command sent yet',ack:'Waiting for a command',dbCounts:{accepted:0,rejected:0,forecasts:0,commands:0,acknowledgements:0},dbRows:[],demoModels:{},activeModel:{model:'gradient_boosting',provenance:'full_validated_study'},proposal:null,reviewText:'No operator decision yet',bMap:{},bRows:[]};
s.replayState=s.replayState||{A:'Waiting for device',B:'Waiting for device'};s.bMap=s.bMap||{};s.bRows=s.bRows||[];s.demoModels=s.demoModels||{};s.activeModel=s.activeModel||{model:'gradient_boosting',provenance:'full_validated_study'};s.outputHistory=s.outputHistory||{};s.busyHistory=s.busyHistory||{};
const t=msg.topic||'';
if(t==='team12/replay/status'&&['A','B','line'].includes(p.company)) s.replayState[p.company]=p.state;
if(t==='team12/ml/train/result') s.demoModels[p.model]=p;
if(t==='team12/db/models'&&Array.isArray(p)) p.forEach(r=>{if(!s.demoModels[r.model]||s.demoModels[r.model].status==='trained')s.demoModels[r.model]={...r,status:'trained'};});
if(t==='team12/ml/active') {if(p.status==='active') s.activeModel=p;else s.modelError=p.error;}
