if(t.startsWith('team12/observed_b/metrics/')) s.bMap[p.asset]={asset:p.asset,status:p.latest_status,reports:p.reports_30m,production:Math.round(100*p.production_share),alarm:Math.round(100*p.alarm_share)};
if(t.startsWith('team12/observed_b/forecast/')) s.bForecast=p;
if(t==='team12/db/b-recent'&&Array.isArray(p)) s.bRows=p;
if(t==='team12/db/counts') s.dbCounts=p;
if(t==='team12/db/recent' && Array.isArray(p)) s.dbRows=p;
if(t.startsWith('team12/observed/metrics/')){
 const output=p.items_per_productive_slot==null?'n/a':Number(p.items_per_productive_slot).toFixed(1);
 s.machineMap[p.asset]={asset:p.asset,output:output,coverage:Math.round(Number(p.coverage||0)*100)};
 const key='Machine '+p.asset;
 s.outputHistory[key]=(s.outputHistory[key]||[]).concat([Number(p.items_per_slot||0)]).slice(-30);
}
if(t.startsWith('team12/forecast/')){
 s.forecastText='Machine '+p.asset+': '+Number(p.predicted_items).toFixed(1)+' items'+(p.prediction_guarded?' (training-range cap)':'');
 const key='Machine '+p.asset;
 s.forecastHistory[key]=(s.forecastHistory[key]||[]).concat([Number(p.predicted_items)]).slice(-30);
}
if(t==='team12/decision/forecast_advisory') s.advice='Machine '+p.asset+': '+p.recommendation;
if(t==='team12/sim/state' && Array.isArray(p.stages)){
 if(typeof p.sim_second==='number' && typeof s.lastSimSecond==='number' && p.sim_second<s.lastSimSecond){s.proposal=null;s.reviewText='Virtual shift restarted';s.action='No command sent yet (new shift)';s.ack='Waiting for a command';s.queueHistory={};s.busyHistory={};}
 s.lastSimSecond=p.sim_second;
 s.arrival=p.arrival_source?{scale:p.arrival_scale,model:p.arrival_source}:null;
 s.stages=p.stages.map(x=>({...x,busy:Math.round(Number(x.busy_share||0)*100)}));
 s.completed=p.line_completed;
 p.stages.forEach(x=>{const key=x.stage_name;s.queueHistory[key]=(s.queueHistory[key]||[]).concat([Number(x.queue_length)]).slice(-30);s.busyHistory[key]=(s.busyHistory[key]||[]).concat([Math.round(Number(x.busy_share||0)*100)]).slice(-30);});
}
if(t==='team12/sim/command') s.action=p.stage_name+': rate '+p.old_rate+' → '+p.new_rate+' tokens/min (command '+p.command_id+')';
if(t==='team12/sim/ack') s.ack=(p.accepted?'Accepted':'Rejected')+' command '+p.command_id+(p.accepted?'':': '+p.reason);
const colors=['#087ba5','#d97706','#4e70b5','#64748b'];
function lines(history,ceiling){
 const names=Object.keys(history).sort();
 const max=ceiling||Math.max(1,...names.flatMap(n=>history[n]));
 return {max:Math.ceil(max),lines:names.map((name,i)=>({name,color:colors[i%colors.length],points:history[name].map((v,j,a)=>(5+(a.length===1?0:j/(a.length-1)*93)).toFixed(1)+','+(95-v/max*85).toFixed(1)).join(' ')}))};
}
const f=lines(s.forecastHistory),q=lines(s.queueHistory),o=lines(s.outputHistory),b=lines(s.busyHistory,100);
const trained=Object.entries(s.demoModels).filter(([name,r])=>r.status==='trained'&&Number.isFinite(Number(r.active_mae)));
trained.sort((a,b)=>Number(a[1].active_mae)-Number(b[1].active_mae));
const demoLeader=trained.length===3?trained[0][0]+' (active MAE '+trained[0][1].active_mae+')':'Train all three to compare the quick-run scores';
const bStatuses=['Production','Standby','MachineOn','Loading','Tooling','Alarm'];
const bValues=Object.values(s.bMap);
const bStatusBars=bStatuses.map(name=>({name,count:bValues.filter(x=>x.status===name).length,pct:bValues.length?Math.round(100*bValues.filter(x=>x.status===name).length/bValues.length):0}));
context.set('overview',s);
msg.payload={arrival:s.arrival||null,replayState:s.replayState,machines:Object.values(s.machineMap).sort((a,b)=>a.asset-b.asset),forecastText:s.forecastText,advice:s.advice,action:s.action,ack:s.ack,stages:s.stages,completed:s.completed,forecastLines:f.lines,forecastMax:f.max,queueLines:q.lines,queueMax:q.max,outputLines:o.lines,outputMax:o.max,busyLines:b.lines,busyMax:b.max,dbCounts:s.dbCounts||{},dbRows:s.dbRows||[],demoModels:s.demoModels,demoLeader:demoLeader,activeModel:s.activeModel,modelError:s.modelError,proposal:s.proposal,reviewText:s.reviewText,bMachines:bValues.sort((a,b)=>a.asset-b.asset),bRows:s.bRows,bStatusBars:bStatusBars,bForecast:s.bForecast};
return msg;

const counts={topic:"SELECT (SELECT COUNT(*) FROM machine_events) AS accepted, (SELECT COUNT(*) FROM company_b_events) AS b_accepted, (SELECT COUNT(*) FROM company_b_metrics) AS b_metrics, (SELECT COUNT(*) FROM rejected_records) AS rejected, (SELECT COUNT(*) FROM forecasts) AS forecasts, (SELECT COUNT(*) FROM forecasts WHERE prediction_guarded=1) AS guarded_forecasts, (SELECT COUNT(*) FROM sim_commands WHERE direction='command') AS commands, (SELECT COUNT(*) FROM sim_commands WHERE direction='ack' AND accepted=1) AS acknowledgements, (SELECT COUNT(*) FROM ml_demo_runs) AS demo_trainings, (SELECT COUNT(*) FROM sim_reviews WHERE decision='accept') AS operator_accepts, (SELECT COUNT(*) FROM sim_reviews WHERE decision='reject') AS operator_rejects, (SELECT ROUND(100.0*SUM(CASE WHEN status=3 THEN 1 ELSE 0 END)/NULLIF(SUM(CASE WHEN status IN (1,2,3) THEN 1 ELSE 0 END),0),1) FROM machine_events) AS a_alarm_pct, (SELECT ROUND(100.0*SUM(CASE WHEN status='Alarm' THEN 1 ELSE 0 END)/NULLIF(SUM(CASE WHEN status IN ('Production','Alarm') THEN 1 ELSE 0 END),0),1) FROM company_b_events) AS b_alarm_pct, (SELECT MIN(100,ROUND(500.0*SUM(CASE WHEN status=3 THEN 1 ELSE 0 END)/NULLIF(SUM(CASE WHEN status IN (1,2,3) THEN 1 ELSE 0 END),0),1)) FROM machine_events) AS a_alarm_bar, (SELECT MIN(100,ROUND(500.0*SUM(CASE WHEN status='Alarm' THEN 1 ELSE 0 END)/NULLIF(SUM(CASE WHEN status IN ('Production','Alarm') THEN 1 ELSE 0 END),0),1)) FROM company_b_events) AS b_alarm_bar, (SELECT COUNT(*) FROM loop_metrics WHERE metric='command_round_trip_ms') AS rt_n, (SELECT ROUND(AVG(value)) FROM loop_metrics WHERE metric='command_round_trip_ms') AS rt_avg, (SELECT ROUND(MAX(value)) FROM loop_metrics WHERE metric='command_round_trip_ms') AS rt_max, (SELECT ROUND(value) FROM loop_metrics WHERE metric='command_round_trip_ms' ORDER BY value LIMIT 1 OFFSET (SELECT CAST(ROUND(0.95*(COUNT(*)-1)) AS INTEGER) FROM loop_metrics WHERE metric='command_round_trip_ms')) AS rt_p95, (SELECT COUNT(*) FROM loop_metrics WHERE metric='ingest_to_forecast_ms') AS ing_n, (SELECT ROUND(AVG(value)) FROM loop_metrics WHERE metric='ingest_to_forecast_ms') AS ing_avg, (SELECT ROUND(MAX(value)) FROM loop_metrics WHERE metric='ingest_to_forecast_ms') AS ing_max, (SELECT ROUND(value) FROM loop_metrics WHERE metric='ingest_to_forecast_ms' ORDER BY value LIMIT 1 OFFSET (SELECT CAST(ROUND(0.95*(COUNT(*)-1)) AS INTEGER) FROM loop_metrics WHERE metric='ingest_to_forecast_ms')) AS ing_p95, (SELECT ROUND(AVG(value),1) FROM loop_metrics WHERE metric='forecast_compute_ms') AS fc_avg, (SELECT COUNT(*) FROM sim_commands WHERE direction='ack' AND accepted=0) AS refused_acks, (SELECT ROUND(MIN(value)) FROM loop_metrics WHERE metric='command_gap_s') AS min_cmd_gap, (SELECT COUNT(*) FROM loop_metrics WHERE metric='command_gap_s') AS gap_n, (SELECT COUNT(*) FROM machine_events WHERE run_id=(SELECT run_id FROM machine_events ORDER BY id DESC LIMIT 1)) AS a_run, (SELECT COUNT(*) FROM company_b_events WHERE run_id=(SELECT run_id FROM company_b_events ORDER BY id DESC LIMIT 1)) AS b_run",payload:[]};
const recent={topic:"SELECT id, asset, substr(ts_dataset,1,16) AS ts_dataset, items, CASE status WHEN 1 THEN 'manual' WHEN 2 THEN 'automatic' WHEN 3 THEN 'alarm' ELSE 'other' END AS state FROM machine_events ORDER BY id DESC LIMIT 5",payload:[]};
const models={topic:"SELECT r.*, COALESCE(r.seed,42) AS seed_used, s.n_seeds, s.mean_mae, s.min_mae, s.max_mae FROM ml_demo_runs r JOIN (SELECT model,MAX(id) AS last_id FROM ml_demo_runs GROUP BY model) latest ON r.id=latest.last_id JOIN (SELECT model, COUNT(*) AS n_seeds, ROUND(AVG(mae),3) AS mean_mae, MIN(mae) AS min_mae, MAX(mae) AS max_mae FROM (SELECT model, COALESCE(seed,42) AS sd, MAX(active_mae) AS mae FROM ml_demo_runs GROUP BY model, sd) GROUP BY model) s ON s.model=r.model",payload:[]};const bRecent={topic:"SELECT id,asset,substr(ts_dataset,1,16) AS ts_dataset,status FROM company_b_events ORDER BY id DESC LIMIT 8",payload:[]};return [counts,recent,models,bRecent];

const p=msg.payload;
if(p.status!=='trained') return null;
return {topic:'INSERT INTO ml_demo_runs (ts_replay,model,train_rows,valid_rows,active_valid_rows,active_mae,idle_mae,overall_mae,train_seconds,seed) VALUES ($ts,$m,$tr,$vr,$av,$a,$i,$o,$s,$seed)',params:{$ts:p.ts_replay,$m:p.model,$tr:p.train_rows,$vr:p.valid_rows,$av:p.active_valid_rows,$a:p.active_mae,$i:p.idle_mae,$o:p.overall_mae,$s:p.train_seconds,$seed:Number.isInteger(p.seed)?p.seed:null}};

const p=msg.payload||{};
const allowed=['ridge','gradient_boosting','neural_network'];
let dest,body;
if(p.kind==='train'&&allowed.includes(p.model)){
 dest='team12/ml/train/request';body={model:p.model};if(p.seed==='new')body.seed='new';
}else if(p.kind==='select'&&(allowed.includes(p.model)||p.model==='validated_winner')){
 dest='team12/ml/select';body={model:p.model};
}else if(p.kind==='review'&&['accept','reject'].includes(p.decision)&&/^[a-f0-9]{8}$/.test(p.proposal_id||'')){
 dest='team12/sim/approval';body={proposal_id:p.proposal_id,decision:p.decision};
}else if(p.kind==='replay'&&['A','B'].includes(p.company)){
 dest='team12/replay/control';body={action:'start',company:p.company};
}else if(p.kind==='line_restart'){
 dest='team12/replay/control';body={action:'restart_line'};
}else return null;
return {topic:dest,payload:JSON.stringify(body)};

const m=msg.payload;
let reason=null;
const states=['Alarm','Standby','MachineOn','Production','Loading','Tooling'];
if(!m||typeof m!=='object'||Array.isArray(m)) reason='B payload not an object';
else if(!Number.isInteger(m.asset)) reason='B asset not an integer';
else if(typeof m.ts_dataset!=='string'||!Number.isFinite(Date.parse(m.ts_dataset))||typeof m.ts_replay!=='string'||!Number.isFinite(Date.parse(m.ts_replay))) reason='B timestamp invalid';
else if(!states.includes(m.status)) reason='B status not documented';
else if(m.source!=='observed_b'||m.company!=='B') reason='B source mismatch';
if(reason) return [null,{topic:'INSERT INTO rejected_records (ts_replay,topic,reason,raw_payload) VALUES ($ts,$topic,$reason,$raw)',params:{$ts:new Date().toISOString(),$topic:msg.topic,$reason:reason,$raw:JSON.stringify(m)}}];
return [{topic:'INSERT OR IGNORE INTO company_b_events (source,run_id,seq,asset,ts_dataset,ts_replay,status,power_avg,alarm_time,loading_time,tooling_time,maintenance_time,support_time) VALUES ($source,$run,$seq,$asset,$tsd,$tsr,$status,$power,$alarm,$loading,$tooling,$maintenance,$support)',validated_payload:m,params:{$source:'observed_b',$run:m.run_id,$seq:m.seq,$asset:m.asset,$tsd:m.ts_dataset,$tsr:m.ts_replay,$status:m.status,$power:Number.isFinite(m.power_avg)?m.power_avg:null,$alarm:m.alarm_time,$loading:m.loading_time,$tooling:m.tooling_time,$maintenance:m.maintenance_time,$support:m.support_time}},null];

const m=msg.validated_payload;
if(!m)return null;
return {topic:'team12/observed_b/validated/'+m.asset,payload:JSON.stringify(m)};

const p = msg.payload;
const known = ['command_round_trip_ms','ingest_to_forecast_ms','forecast_compute_ms','command_gap_s'];
